package apihub_test

import (
	"fmt"
	"log"
	"os"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/hashicorp/terraform-provider-google/google/envvar"
	"github.com/hashicorp/terraform-provider-google/google/services/apihub"
	"github.com/hashicorp/terraform-provider-google/google/services/resourcemanager"
	transport_tpg "github.com/hashicorp/terraform-provider-google/google/transport"
)

const (
	bootstrapApihubProjectPrefix = "tf-boot-apihub-"
	bootstrapApihubLocation      = "us-central1"
	bootstrapApihubInstanceWait  = 90 * time.Minute
)

var (
	bootstrapApihubMu    sync.Mutex
	bootstrapApihubCache = make(map[string]string)
)

func bootstrapApihubProjectID() string {
	suffix := strings.Replace(envvar.GetTestProjectFromEnv(), "ci-test-project-", "", 1)
	return bootstrapApihubProjectPrefix + suffix
}

// BootstrapApihubInstanceProject returns a persistent isolated test project
// with an ACTIVE API Hub instance in us-central1, creating the project, host
// project registration, and instance on first use.
//
// Creating a new API Hub instance takes 25-60+ minutes and an instance cannot
// be deleted independently of its project, so reusing one persistent project
// per test environment avoids provisioning a new project and instance on every
// test run.
func BootstrapApihubInstanceProject(t *testing.T) string {
	t.Helper()

	if os.Getenv("VCR_MODE") == "REPLAYING" {
		return bootstrapApihubProjectID()
	}

	config := transport_tpg.BootstrapConfig(t)
	if config == nil {
		return ""
	}

	bootstrapApihubMu.Lock()
	defer bootstrapApihubMu.Unlock()

	if project, ok := bootstrapApihubCache[bootstrapApihubProjectPrefix]; ok {
		return project
	}

	p := resourcemanager.BootstrapProject(t, bootstrapApihubProjectPrefix, envvar.GetTestBillingAccountFromEnv(t), []string{"apihub.googleapis.com"})
	if p == nil {
		t.Fatal("Bootstrapping failed. Could not bootstrap the isolated API Hub test project.")
	}

	ensureApihubInstance(t, config, p.ProjectId)

	bootstrapApihubCache[bootstrapApihubProjectPrefix] = p.ProjectId
	return p.ProjectId
}

func ensureApihubInstance(t *testing.T, config *transport_tpg.Config, project string) {
	t.Helper()

	state := lookupApihubInstanceState(t, config, project)
	switch state {
	case "ACTIVE":
		return
	case "CREATING", "UPDATING":
		waitForApihubInstanceActive(t, config, project)
		return
	case "":
		// No instance exists (or any previous instance is INACTIVE).
	default:
		t.Fatalf("Bootstrapping failed. API Hub instance in %s is in unexpected state %q.", project, state)
	}

	ensureApihubHostProjectRegistration(t, config, project)

	createURL := fmt.Sprintf("%sprojects/%s/locations/%s/apiHubInstances", transport_tpg.BaseUrl(apihub.Product, config), project, bootstrapApihubLocation)
	log.Printf("[DEBUG] Creating bootstrapped API Hub instance in %s", project)
	op, err := apihubBootstrapRequest(config, project, "POST", createURL, map[string]interface{}{
		"config": map[string]interface{}{
			"disableSearch": true,
		},
	})
	if err != nil {
		if transport_tpg.IsGoogleApiErrorWithCode(err, 409) {
			waitForApihubInstanceActive(t, config, project)
			return
		}
		t.Fatalf("Bootstrapping failed. Error creating API Hub instance in %s: %s", project, err)
	}

	if err := apihub.ApihubOperationWaitTime(config, op, project, "Creating bootstrapped ApiHubInstance", config.UserAgent, bootstrapApihubInstanceWait); err != nil {
		t.Fatalf("Bootstrapping failed. Error waiting for API Hub instance creation in %s: %s", project, err)
	}
	waitForApihubInstanceActive(t, config, project)
}

func ensureApihubHostProjectRegistration(t *testing.T, config *transport_tpg.Config, project string) {
	t.Helper()

	baseURL := transport_tpg.BaseUrl(apihub.Product, config)
	getURL := fmt.Sprintf("%sprojects/%s/locations/%s/hostProjectRegistrations/%s", baseURL, project, bootstrapApihubLocation, project)
	_, err := apihubBootstrapRequest(config, project, "GET", getURL, nil)
	if err == nil {
		return
	}
	if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
		t.Fatalf("Bootstrapping failed. Error getting API Hub host project registration in %s: %s", project, err)
	}

	createURL := fmt.Sprintf("%sprojects/%s/locations/%s/hostProjectRegistrations?hostProjectRegistrationId=%s", baseURL, project, bootstrapApihubLocation, project)
	log.Printf("[DEBUG] Creating bootstrapped API Hub host project registration in %s", project)
	_, err = apihubBootstrapRequest(config, project, "POST", createURL, map[string]interface{}{
		"gcpProject": "projects/" + project,
	})
	if err != nil && !transport_tpg.IsGoogleApiErrorWithCode(err, 409) {
		t.Fatalf("Bootstrapping failed. Error creating API Hub host project registration in %s: %s", project, err)
	}
}

func lookupApihubInstanceState(t *testing.T, config *transport_tpg.Config, project string) string {
	t.Helper()

	lookupURL := fmt.Sprintf("%sprojects/%s/locations/%s/apiHubInstances:lookup", transport_tpg.BaseUrl(apihub.Product, config), project, bootstrapApihubLocation)
	res, err := apihubBootstrapRequest(config, project, "GET", lookupURL, nil)
	if err != nil {
		t.Fatalf("Bootstrapping failed. Error looking up API Hub instance in %s: %s", project, err)
	}
	inst, ok := res["apiHubInstance"].(map[string]interface{})
	if !ok || inst == nil {
		return ""
	}
	state, _ := inst["state"].(string)
	return state
}

func waitForApihubInstanceActive(t *testing.T, config *transport_tpg.Config, project string) {
	t.Helper()

	deadline := time.Now().Add(bootstrapApihubInstanceWait)
	for {
		state := lookupApihubInstanceState(t, config, project)
		switch state {
		case "ACTIVE":
			return
		case "CREATING", "UPDATING":
			if time.Now().After(deadline) {
				t.Fatalf("Bootstrapping failed. Timed out waiting for API Hub instance in %s to become ACTIVE (last state: %q).", project, state)
			}
			time.Sleep(15 * time.Second)
		default:
			t.Fatalf("Bootstrapping failed. API Hub instance in %s entered unexpected state %q while waiting for ACTIVE.", project, state)
		}
	}
}

func apihubBootstrapRequest(config *transport_tpg.Config, project, method, url string, body map[string]interface{}) (map[string]interface{}, error) {
	return transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:               config,
		Method:               method,
		Project:              project,
		RawURL:               url,
		UserAgent:            config.UserAgent,
		Body:                 body,
		Timeout:              5 * time.Minute,
		ErrorRetryPredicates: []transport_tpg.RetryErrorPredicateFunc{isApihubBootstrapRetryableError},
	})
}

func isApihubBootstrapRetryableError(err error) (bool, string) {
	if err == nil {
		return false, ""
	}
	if transport_tpg.IsGoogleApiErrorWithCode(err, 403) {
		return true, "Waiting for project IAM permissions and API Hub service activation to propagate"
	}
	if transport_tpg.IsGoogleApiErrorWithCode(err, 400) && strings.Contains(err.Error(), "Invalid project") {
		return true, "Waiting for newly created project to propagate to API Hub resource cache"
	}
	return false, ""
}
